/* CastUserSnapshotMapper.insertRsrcMstr */
INSERT INTO PMOWN.${mstrTableNm} (
    ${mstrIdColumnNm}, ${mstrNmColumnNm}, PRCS_STTS_CD, CFMTN_YN, USE_YN,
    FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT
) VALUES (
    #{snapshot.rsrcNo},
    '사용자 시뮬레이션 ' || #{snapshot.smltId},
    '99', 'Y', 'Y',
    #{snapshot.loginUserId}, #{snapshot.loginIpAddr}, CURRENT_TIMESTAMP
)

/* CastUserSnapshotMapper.insertSchdlAtrbFromDaily */ INSERT INTO PMOWN.TN_PM_SMLT_SCHDL_ATRB ( SCHDL_ATRB_GROUP_ID, DOM_INTL_SE_CD, ARR_DEP_SE_CD, TMNL_ID, ALN_CD, ALN_CTGRY, FLTNM, DEP_ARR_YMD, DEP_ARR_HM, PREDC_HM, ACTL_HM, ARR_DEP_ARPT_CD, ACST_NO, GATE_NO, GATE_TYPE, ARCFT_STGCP, BDPSG_CNT, TRNS_BDPSG_CNT, CRSL_NO, ARCFT_SUBTYPE_CD, CKNCT_RANGE_CN, SLF_CHKN_PSBLTY_YN, IRR_FLT_YN, TDFLT_YN, BUS_NEED_YN, WAYO_ID, FRST_BAG_INPUT_DT, LAST_BAG_INPUT_DT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH AJMT AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS NUMBER) AS AJMT_RT FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.ajmtRt} FROM DUAL
) SELECT #{rsrcNo}, X.DOM_INTL_SE_CD, X.FLIGHTDIRECTION, X.DEPARRTERMINAL, X.AIRLINECODE, X.OPERATORCAT, X.FLIGHTNUMBER, X.SCHD_DT, X.SCHD_HM, X.PREDC_HM, X.ACTL_HM, X.AIRPORTCODE, X.STANDNUMBER, X.GATE, X.CONTACTREMOTE, X.SEATS, X.PAXCOUNT + ROUND( CASE WHEN X.FLIGHTDIRECTION = 'D' AND X.DOM_INTL_SE_CD != 'D' THEN GREATEST( NVL(TO_NUMBER(TRIM(X.RSVT_BDPSG_CNT)), 0) - NVL(TO_NUMBER(TRIM(X.RSVT_TRNS_BDPSG_CNT)), 0), 0 ) ELSE 0 END * X.AJMT_RT / 100 ), X.TRANSFERPAX, X.BELT, X.AIRCRAFTTYPE, X.CHECKINRANGE, X.SBDAVAILABLE, X.GD_IRR_YN, X.TRIANGLE, X.BUS, X.ARRIVALGATE, TO_TIMESTAMP(SUBSTR(X.FRST_BAG_INPUT_DT_RAW, 1, 12), 'YYYYMMDDHH24MI'), TO_TIMESTAMP(SUBSTR(X.LAST_BAG_INPUT_DT_RAW, 1, 12), 'YYYYMMDDHH24MI'), #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM ( SELECT F.*, NVL(( SELECT NVL(J.AJMT_RT, 0) FROM AJMT J WHERE J.TMNL_ID = DECODE(F.CF_TER_ID_X, 'P01', 'P01', 'P02', 'P01', 'P03', 'P03') ), 0) AS AJMT_RT, ROW_NUMBER() OVER ( PARTITION BY F.FLIGHTDIRECTION, F.FLIGHTNUMBER, F.SCHD_DT, F.SCHD_HM ORDER BY F.RSVT_BDPSG_CNT DESC NULLS LAST ) AS RN FROM (
) F WHERE F.SCHD_HM IS NOT NULL ) X WHERE X.RN = 1

/* CastUserSnapshotMapper.insertSchdlAtrbFromSrc */ INSERT INTO PMOWN.TN_PM_SMLT_SCHDL_ATRB ( SCHDL_ATRB_GROUP_ID, DOM_INTL_SE_CD, ARR_DEP_SE_CD, TMNL_ID, ALN_CD, ALN_CTGRY, FLTNM, DALY_FLTSH_ID, DEP_ARR_YMD, DEP_ARR_HM, PREDC_HM, ACTL_HM, ARR_DEP_ARPT_CD, ACST_NO, GATE_NO, GATE_TYPE, ARCFT_STGCP, BDPSG_CNT, TRNS_BDPSG_CNT, CRSL_NO, ARCFT_SUBTYPE_CD, CKNCT_RANGE_CN, SLF_CHKN_PSBLTY_YN, IRR_FLT_YN, TDFLT_YN, BUS_NEED_YN, WAYO_ID, FRST_BAG_INPUT_DT, LAST_BAG_INPUT_DT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH AJMT AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS NUMBER) AS AJMT_RT FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.ajmtRt} FROM DUAL
) SELECT #{rsrcNo}, A.DOM_INTL_SE_CD, A.ARR_DEP_SE_CD, A.TMNL_ID, A.ALN_CD, A.ALN_CTGRY, A.FLTNM, A.DALY_FLTSH_ID, A.DEP_ARR_YMD, A.DEP_ARR_HM, A.PREDC_HM, A.ACTL_HM, A.ARR_DEP_ARPT_CD, A.ACST_NO, A.GATE_NO, A.GATE_TYPE, A.ARCFT_STGCP, NVL(A.BDPSG_CNT, 0) + ROUND( CASE WHEN A.ARR_DEP_SE_CD = 'D' AND A.DOM_INTL_SE_CD != 'D' THEN GREATEST(NVL(A.BDPSG_CNT, 0) - NVL(A.TRNS_BDPSG_CNT, 0), 0) ELSE 0 END * NVL(( SELECT NVL(F.AJMT_RT, 0) FROM AJMT F WHERE F.TMNL_ID = DECODE(A.TMNL_ID, 'P01', 'P01', 'P02', 'P01', 'P03', 'P03') ), 0) / 100 ), A.TRNS_BDPSG_CNT, A.CRSL_NO, A.ARCFT_SUBTYPE_CD, A.CKNCT_RANGE_CN, A.SLF_CHKN_PSBLTY_YN, A.IRR_FLT_YN, A.TDFLT_YN, NVL(A.BUS_NEED_YN, 'N'), A.WAYO_ID, A.FRST_BAG_INPUT_DT, A.LAST_BAG_INPUT_DT, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM PMOWN.TN_PM_SMLT_SCHDL_ATRB A WHERE A.SCHDL_ATRB_GROUP_ID = REPLACE(#{srcFltSchdlRsrcId}, 'FS', '')

/* CastUserSnapshotMapper.insertCknctAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_CKNCT_ATRB ( SCHDL_ATRB_GROUP_ID, BLCK_ID, TMNL_ID, CKNCT_ID, ALN_CD, DOM_INTL_SE_CD, CRTR_YMD, CHKN_OPEN_PRNMNT_DT, CHKN_CLOSE_PRNMNT_DT, CHKN_TYPE_CD, CHKN_TYPE_DTL_INFO, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH BOOTH AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(1)) AS CHKN_ISL_CD, CAST(NULL AS NUMBER) AS BOOTH_NO, CAST(NULL AS VARCHAR2(3)) AS ALN_CD FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.chknIslCd}, #{row.boothNo}, #{row.alnCd} FROM DUAL
), OPER_HR AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(1)) AS CHKN_ISL_CD, CAST(NULL AS NUMBER) AS OPER_HR_SN, CAST(NULL AS NUMBER) AS OPER_BGNG_HOUR, CAST(NULL AS NUMBER) AS OPER_END_HOUR FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.fcltCd}, #{row.operHrSn}, #{row.operBgngHour}, #{row.operEndHour} FROM DUAL
) SELECT #{rsrcNo}, CASE WHEN B.TMNL_ID = 'P03' THEN 'P03CKIN' WHEN NVL(C.DOM_INTL_SE_CD, 'I') = 'I' THEN 'P01CKINInt' ELSE 'P01CKINDom' END, B.TMNL_ID, C.CKNCT_ID, B.ALN_CD, NVL(C.DOM_INTL_SE_CD, 'I'), #{excnYmd}, #{excnYmd} || LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', #{excnYmd} || LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), 'C', B.ALN_CD, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM BOOTH B INNER JOIN OPER_HR H ON H.TMNL_ID = B.TMNL_ID AND H.CHKN_ISL_CD = B.CHKN_ISL_CD INNER JOIN ( SELECT K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) AS CHKN_ISL_CD, K.CKNCT_ID, K.DOM_INTL_SE_CD, ROW_NUMBER() OVER (PARTITION BY K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) ORDER BY K.CKNCT_ID) AS BOOTH_NO FROM CAOWN.TN_CA_CKNCT K WHERE K.USE_YN = 'Y' AND K.CKNCT_USE_CRG_APLCN_TYPE_CD IN ('A', 'B') ) C ON C.TMNL_ID = B.TMNL_ID AND C.CHKN_ISL_CD = B.CHKN_ISL_CD AND C.BOOTH_NO = B.BOOTH_NO WHERE B.ALN_CD IS NOT NULL

/* CastUserSnapshotMapper.insertSbdAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_SBD_ATRB ( SCHDL_ATRB_GROUP_ID, BLCK_ID, TMNL_ID, CKNCT_ID, ALN_CD, DOM_INTL_SE_CD, CRTR_YMD, OPER_BGNG_DT, OPER_END_DT, CHKN_TYPE_CD, CHKN_TYPE_DTL_INFO, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH ISL AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(1)) AS CHKN_ISL_CD, CAST(NULL AS NUMBER) AS KOS_CNT, CAST(NULL AS NUMBER) AS SBD_CNT FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.chknIslCd}, #{row.kosCnt}, #{row.sbdCnt} FROM DUAL
), OPER_HR AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(1)) AS CHKN_ISL_CD, CAST(NULL AS NUMBER) AS OPER_HR_SN, CAST(NULL AS NUMBER) AS OPER_BGNG_HOUR, CAST(NULL AS NUMBER) AS OPER_END_HOUR FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.fcltCd}, #{row.operHrSn}, #{row.operBgngHour}, #{row.operEndHour} FROM DUAL
), BOOTH AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(1)) AS CHKN_ISL_CD, CAST(NULL AS NUMBER) AS BOOTH_NO, CAST(NULL AS VARCHAR2(3)) AS ALN_CD FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.chknIslCd}, #{row.boothNo}, #{row.alnCd} FROM DUAL
) SELECT #{rsrcNo}, CASE WHEN I.TMNL_ID = 'P03' THEN 'P03SBD' ELSE 'P01SBD' END, I.TMNL_ID, C.CKNCT_ID, A.ALN_CD, NVL(C.DOM_INTL_SE_CD, 'I'), #{excnYmd}, #{excnYmd} || LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', #{excnYmd} || LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), 'C', SUBSTR(A.ALN_CD_LIST, 1, 200), #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM ISL I INNER JOIN OPER_HR H ON H.TMNL_ID = I.TMNL_ID AND H.CHKN_ISL_CD = I.CHKN_ISL_CD INNER JOIN ( SELECT K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) AS CHKN_ISL_CD, K.CKNCT_ID, K.DOM_INTL_SE_CD, ROW_NUMBER() OVER (PARTITION BY K.TMNL_ID, SUBSTR(K.CKNCT_ID, 1, 1) ORDER BY K.CKNCT_ID) AS DEVICE_NO FROM CAOWN.TN_CA_CKNCT K WHERE K.USE_YN = 'Y' AND K.CKNCT_USE_CRG_APLCN_TYPE_CD = 'H' ) C ON C.TMNL_ID = I.TMNL_ID AND C.CHKN_ISL_CD = I.CHKN_ISL_CD AND C.DEVICE_NO <= NVL(I.SBD_CNT, 0) LEFT OUTER JOIN ( SELECT TMNL_ID, CHKN_ISL_CD, MIN(ALN_CD) AS ALN_CD, LISTAGG(ALN_CD, ',') WITHIN GROUP (ORDER BY ALN_CD) AS ALN_CD_LIST FROM ( SELECT DISTINCT TMNL_ID, CHKN_ISL_CD, ALN_CD FROM BOOTH WHERE ALN_CD IS NOT NULL ) GROUP BY TMNL_ID, CHKN_ISL_CD ) A ON A.TMNL_ID = I.TMNL_ID AND A.CHKN_ISL_CD = I.CHKN_ISL_CD

/* CastUserSnapshotMapper.insertSbdAtrbKiosk */ INSERT INTO PMOWN.TN_PM_SMLT_SBD_ATRB ( SCHDL_ATRB_GROUP_ID, BLCK_ID, TMNL_ID, CKNCT_ID, ALN_CD, DOM_INTL_SE_CD, CRTR_YMD, OPER_BGNG_DT, OPER_END_DT, CHKN_TYPE_CD, CHKN_TYPE_DTL_INFO, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH ISL AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(1)) AS CHKN_ISL_CD, CAST(NULL AS NUMBER) AS KOS_CNT, CAST(NULL AS NUMBER) AS SBD_CNT FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.chknIslCd}, #{row.kosCnt}, #{row.sbdCnt} FROM DUAL
), OPER_HR AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(1)) AS CHKN_ISL_CD, CAST(NULL AS NUMBER) AS OPER_HR_SN, CAST(NULL AS NUMBER) AS OPER_BGNG_HOUR, CAST(NULL AS NUMBER) AS OPER_END_HOUR FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.fcltCd}, #{row.operHrSn}, #{row.operBgngHour}, #{row.operEndHour} FROM DUAL
) SELECT #{rsrcNo}, CASE WHEN I.TMNL_ID = 'P03' THEN 'P03Self' ELSE 'P01Self' END, I.TMNL_ID, C.SLF_CHKN_ISTR_ID, C.ALN_CD, 'I', #{excnYmd}, #{excnYmd} || LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', #{excnYmd} || LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), 'C', SUBSTR(C.ALN_CD_LIST, 1, 200), #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM ISL I INNER JOIN OPER_HR H ON H.TMNL_ID = I.TMNL_ID AND H.CHKN_ISL_CD = I.CHKN_ISL_CD INNER JOIN ( SELECT P.TMNL_ID, SUBSTR(P.SLF_CHKN_ISTR_ID, -3, 1) AS CHKN_ISL_CD, P.SLF_CHKN_ISTR_ID, MIN(P.ALN_CD) AS ALN_CD, LISTAGG(P.ALN_CD, ',') WITHIN GROUP (ORDER BY P.ALN_CD) AS ALN_CD_LIST, ROW_NUMBER() OVER (PARTITION BY P.TMNL_ID, SUBSTR(P.SLF_CHKN_ISTR_ID, -3, 1) ORDER BY P.SLF_CHKN_ISTR_ID) AS DEVICE_NO FROM PMOWN.TN_PM_SLF_CHKN_OPER_PLCY P WHERE #{excnYmd} BETWEEN P.PLCY_BGNG_YMD AND P.PLCY_END_YMD
GROUP BY P.TMNL_ID, SUBSTR(P.SLF_CHKN_ISTR_ID, -3, 1), P.SLF_CHKN_ISTR_ID ) C ON C.TMNL_ID = I.TMNL_ID AND C.CHKN_ISL_CD = I.CHKN_ISL_CD AND C.DEVICE_NO <= NVL(I.KOS_CNT, 0)

/* CastUserSnapshotMapper.insertDptgtAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_FCLTY_OPNG_DPTGT_ATRB ( DPTGT_ATRB_ID, FCLTY_OPNG_SN, TMNL_ID, FCLT_SE_CD, GATE_NO, SD_DR, FCLT_RCG, FCLTY_TYPE_ID, FCLTY_CNT, OPER_BGNG_HM, OPER_END_HM, GNRL_SRCH_CNTOM, SMART_PASS_SRCH_CNTOM, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH DPTGT AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(2)) AS DPTGT_NO, CAST(NULL AS VARCHAR2(1)) AS OPER_YN, CAST(NULL AS NUMBER) AS SCSH_CNTOM, CAST(NULL AS NUMBER) AS GNRL_SRCH_CNTOM, CAST(NULL AS NUMBER) AS SMART_PASS_SRCH_CNTOM FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.dptgtNo}, #{row.oprYn}, #{row.scshCntom}, #{row.gnrlSrchCntom}, #{row.smartPassSrchCntom} FROM DUAL
), OPER_HR AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(2)) AS DPTGT_NO, CAST(NULL AS NUMBER) AS OPER_HR_SN, CAST(NULL AS NUMBER) AS OPER_BGNG_HOUR, CAST(NULL AS NUMBER) AS OPER_END_HOUR FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.fcltCd}, #{row.operHrSn}, #{row.operBgngHour}, #{row.operEndHour} FROM DUAL
), LANE_RAW AS (
SELECT D.TMNL_ID, D.DPTGT_NO, D.GNRL_SRCH_CNTOM, D.SMART_PASS_SRCH_CNTOM, T.FCLT_SE_CD, T.FCLTY_TYPE_ID, T.SD_DR, T.FCLT_RCG, CASE T.FCLT_RCG WHEN 'Y' THEN NVL(D.SMART_PASS_SRCH_CNTOM, 0) WHEN 'N' THEN NVL(D.GNRL_SRCH_CNTOM, 0) ELSE 0 END * NVL( NVL(T.FCLTY_CNT, 0) / NULLIF(SUM(NVL(T.FCLTY_CNT, 0)) OVER (PARTITION BY D.TMNL_ID, D.DPTGT_NO, T.FCLT_RCG), 0), 1 / COUNT(*) OVER (PARTITION BY D.TMNL_ID, D.DPTGT_NO, T.FCLT_RCG) ) AS RAW_CNT, CASE T.FCLT_RCG WHEN 'Y' THEN NVL(D.SMART_PASS_SRCH_CNTOM, 0) WHEN 'N' THEN NVL(D.GNRL_SRCH_CNTOM, 0) ELSE 0 END AS TRGT_CNT FROM DPTGT D INNER JOIN PMOWN.TN_PM_SMLT_FCLTY_OPNG_DPTGT_ATRB T ON T.DPTGT_ATRB_ID = '001' AND T.OPER_BGNG_HM IS NULL AND T.TMNL_ID = D.TMNL_ID AND T.GATE_NO = D.DPTGT_NO WHERE D.OPER_YN = 'Y' ), LANE_BASE AS ( SELECT R.*, FLOOR(R.RAW_CNT) AS BASE_CNT, R.TRGT_CNT - SUM(FLOOR(R.RAW_CNT)) OVER (PARTITION BY R.TMNL_ID, R.DPTGT_NO, R.FCLT_RCG) AS REM_CNT, ROW_NUMBER() OVER ( PARTITION BY R.TMNL_ID, R.DPTGT_NO, R.FCLT_RCG ORDER BY R.RAW_CNT - FLOOR(R.RAW_CNT) DESC, R.FCLTY_TYPE_ID, R.SD_DR ) AS REM_RN FROM LANE_RAW R ) SELECT #{rsrcNo}, ROW_NUMBER() OVER (ORDER BY L.TMNL_ID, L.DPTGT_NO, L.FCLTY_TYPE_ID, L.SD_DR, L.FCLT_RCG, H.OPER_HR_SN), L.TMNL_ID, L.FCLT_SE_CD, L.DPTGT_NO, L.SD_DR, L.FCLT_RCG, L.FCLTY_TYPE_ID, L.BASE_CNT + CASE WHEN L.REM_RN <= L.REM_CNT THEN 1 ELSE 0 END, LPAD(H.OPER_BGNG_HOUR, 2, '0') || '00', LPAD(DECODE(H.OPER_END_HOUR, 24, 23, H.OPER_END_HOUR), 2, '0') || DECODE(H.OPER_END_HOUR, 24, '59', '00'), L.GNRL_SRCH_CNTOM, L.SMART_PASS_SRCH_CNTOM, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM LANE_BASE L INNER JOIN OPER_HR H ON H.TMNL_ID = L.TMNL_ID AND H.DPTGT_NO = L.DPTGT_NO

/* CastUserSnapshotMapper.insertScrtyCntrlAtrb */ INSERT INTO PMOWN.TN_PM_SMLT_FCLTY_OPNG_SCRTY_CNTRL_ATRB ( SCRTY_CNTRL_ATRB_ID, FCLTY_OPNG_SN, TMNL_ID, FCLT_SE_CD, GATE_NO, FCLTY_CNT, FRST_RGTR_ID, FRST_RGTR_IP_ADDR, FRST_REG_DT ) WITH DPTGT AS ( SELECT CAST(NULL AS VARCHAR2(4)) AS TMNL_ID, CAST(NULL AS VARCHAR2(2)) AS DPTGT_NO, CAST(NULL AS VARCHAR2(1)) AS OPER_YN, CAST(NULL AS NUMBER) AS SCSH_CNTOM, CAST(NULL AS NUMBER) AS GNRL_SRCH_CNTOM, CAST(NULL AS NUMBER) AS SMART_PASS_SRCH_CNTOM FROM DUAL WHERE 1 = 0
UNION ALL SELECT #{row.tmnlId}, #{row.dptgtNo}, #{row.oprYn}, #{row.scshCntom}, #{row.gnrlSrchCntom}, #{row.smartPassSrchCntom} FROM DUAL
) SELECT #{rsrcNo}, ROW_NUMBER() OVER (ORDER BY D.TMNL_ID, D.DPTGT_NO), D.TMNL_ID, 'D', D.DPTGT_NO, D.SCSH_CNTOM, #{loginUserId}, #{loginIpAddr}, CURRENT_TIMESTAMP FROM DPTGT D WHERE D.OPER_YN = 'Y' AND D.SCSH_CNTOM > 0
